func TestStatus_WithoutCacheSeesWorktreeChanges(t *testing.T) {
	t.Parallel()

	dir := newRepoWithCommit(t)
	repo, err := gitrepo.OpenPath(dir)
	if err != nil {
		t.Fatalf("OpenPath(%q) error = %v", dir, err)
	}
