	ctx := context.Background()

	status, err := gitrepo.Status(ctx, repo)
	if err != nil {
		t.Fatalf("Status() error = %v", err)
	}
	if _, ok := status["new.txt"]; ok {
		t.Fatalf("Status() reported new.txt before it was created")
